# CDN配置和使用示例

# 1. Nginx配置CDN回源
upstream origin_server {
    server origin.example.com:80;
}

server {
    listen 80;
    server_name cdn.example.com;

    # 静态资源缓存配置
    location ~* \.(jpg|jpeg|png|gif|css|js|woff2)$ {
        proxy_pass http://origin_server;
        proxy_cache_valid 200 1d;      # 200响应缓存1天
        proxy_cache_valid 404 1m;      # 404缓存1分钟
        add_header X-Cache-Status $upstream_cache_status;
        add_header Cache-Control "public, max-age=86400";
    }
}

# 2. 验证CDN是否生效
# 检查响应头中的CDN标识
$ curl -I https://cdn.example.com/image.jpg
# 查看 X-Cache-Status: HIT (缓存命中) / MISS (回源)
# 查看 X-Cache: HIT from cdn-node
# 查看 Via: CDN标识

# 3. 不同CDN提供商的CNAME配置
# 阿里云CDN: cdn.example.com CNAME → cdn.example.com.w.kunlun.com
# 腾讯云CDN: cdn.example.com CNAME → cdn.example.com.cdn.dnsv1.com
# Cloudflare: cdn.example.com CNAME → xxx.cloudflare.net

# 4. 缓存刷新API示例(阿里云)
# 刷新单个URL
$ curl -X POST "https://cdn.aliyuan.com/api/refresh" \
    -d "objectType=File" \
    -d "objectPath=https://cdn.example.com/style.css"

# 目录刷新
$ curl -X POST "https://cdn.aliyuan.com/api/refresh" \
    -d "objectType=Directory" \
    -d "objectPath=https://cdn.example.com/assets/"
